using System;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json;
using EnusDE.Signaltechnik;

public static class FreeLineTests {
    static readonly string stationA=Guid.NewGuid().ToString("N"),stationB=Guid.NewGuid().ToString("N");
    static void Check(bool ok,string text){if(!ok)throw new Exception("FAIL: "+text);System.Console.WriteLine("PASS: "+text);}
    static bool Reject(Action action){try{action();return false;}catch{return true;}}
    static DirectedRouteSection Part(string segment,double from=0,double to=100,bool reverse=false)=>new(){Section=new TrackSection{Segment=segment,From=from,To=to},Reverse=reverse};
    static LineTrackDefinition Line(string segment="S",bool automatic=true,LineTrackMode mode=LineTrackMode.Gleiswechselbetrieb) {
        var d=new LineTrackDefinition{Code="LINE-"+segment,Name="A – B",Track=segment,StationA=stationA,StationB=stationB,Mode=mode,Enabled=true,Automatic=automatic,Topology=new string('a',64),ForwardStart=Guid.NewGuid().ToString("N"),ForwardEnd=Guid.NewGuid().ToString("N"),ReverseStart=Guid.NewGuid().ToString("N"),ReverseEnd=Guid.NewGuid().ToString("N"),Forward=new(){Part(segment)},Reverse=mode==LineTrackMode.Directional?new():new(){Part(segment,reverse:true)}};
        foreach(string id in new[]{d.ForwardStart,d.ForwardEnd,d.ReverseStart,d.ReverseEnd})d.Anchors[id]="anchor";
        d.Validate();return d;
    }
    static RouteDefinition Route(string segment="S",bool reverse=false)=>new(){Code="R",Entry="entry",Exit="exit",Path=new(){Part(segment,10,90,reverse)}};
    static void Reserve(LineDirectionAuthority authority,RouteDefinition route){using var ticket=authority.Reserve(new[]{route});ticket.Commit();}
    static void ClearChecks(LineDirectionAuthority authority,double start=0){for(int i=1;i<=3;i++)authority.Observe(Array.Empty<RouteRun>(),start+i);}
    public static void Run() {
        var line=Line();var axis=LineTrackGeometry.Axis(new[]{Part("S",20,930)},new[]{Part("S",70,980,true)},LineTrackMode.Gleiswechselbetrieb);
        Check(axis.Single().Section.From==70&&axis.Single().Section.To==930&&!axis[0].Reverse,"reciprocal line detection keeps the shared free line while excluding different station terminal portions");
        Check(Reject(()=>LineTrackGeometry.Axis(new[]{Part("S")},new[]{Part("T",reverse:true)},LineTrackMode.Gleiswechselbetrieb)),"opposite routes on different parallel tracks cannot define one GWB track");
        Check(Reject(()=>LineTrackGeometry.Axis(new[]{Part("S")},new[]{Part("S")},LineTrackMode.SingleTrack)),"two paths facing the same direction cannot be treated as opposite line routes");
        Check(Reject(()=>LineTrackGeometry.Axis(new[]{Part("a"),Part("middle"),Part("z")},new[]{Part("z",reverse:true),Part("other",reverse:true),Part("a",reverse:true)},LineTrackMode.Gleiswechselbetrieb)),"opposite line proposals cannot diverge and rejoin through different internal tracks");
        Check(Reject(()=>LineTrackGeometry.Axis(new[]{Part("a"),Part("z")},new[]{Part("a",reverse:true),Part("z",reverse:true)},LineTrackMode.Gleiswechselbetrieb)),"reciprocal paths must visit common segments in reverse order");
        Check(LineTrackGeometry.Normalize(new[]{Part("s",0,40),Part("s",40,100)}).Count==1&&Reject(()=>LineTrackGeometry.Normalize(new[]{Part("s"),Part("loop"),Part("s")})),"adjacent subroutes on one segment merge while loops are rejected");
        var library=new DeskLibrary{WorldKey="world",Desks=new(){new DeskDefinition{Global=true,Code="ESTW",Name="Master",Panel=new(){WorldKey="world"}},new DeskDefinition{Id=stationA,Code="A",Name="A",Panel=new(){WorldKey="world"}},new DeskDefinition{Id=stationB,Code="B",Name="B",Panel=new(){WorldKey="world"}}},FreeLines=new(){line}};
        library.Validate("world");var round=JsonConvert.DeserializeObject<DeskLibrary>(JsonConvert.SerializeObject(library));round.Validate("world");
        Check(round.FreeLines.Single().Mode==LineTrackMode.Gleiswechselbetrieb&&round.FreeLines[0].Axis.Single().Section.Segment=="S","free-line modes, endpoints and physical paths survive shared save transfer");
        var copy=library.Clone();copy.FreeLines[0].Forward[0].Section.To=75;copy.FreeLines[0].Anchors.Clear();Check(library.FreeLines[0].Forward[0].Section.To==100&&library.FreeLines[0].Anchors.Count==4,"line configuration deep-clones physical paths and endpoint snapshots");
        copy=library.Clone();copy.FreeLines.Add(Line());copy.FreeLines[1].Code="ANOTHER";Check(Reject(()=>copy.Validate("world")),"two enabled permissions cannot overlap the same physical line track");
        copy=library.Clone();copy.FreeLines.Add(Line("T"));copy.Validate("world");Check(copy.FreeLines.Count==2,"parallel physical tracks can hold separate line definitions");
        copy=library.Clone();copy.FreeLines[0].StationB=Guid.NewGuid().ToString("N");Check(Reject(()=>copy.Validate("world")),"losing a neighbouring interlocking cannot silently orphan its line permission");
        var indicator=new PanelTile{Kind=PanelTileKind.LinePermission,X=2,Y=2,Reference=line.Id};library.Desks[0].Panel.Put(indicator);library.Validate("world");
        var deletion=new DeskRemoval(library,stationA);var deleted=deletion.Apply(library,Array.Empty<RouteDefinition>());
        Check(deletion.LinkedLines==1&&deleted.FreeLines.Count==0&&deleted.Desks[0].Panel.At(2,2).Reference==""&&library.FreeLines.Count==1,"confirmed station deletion removes connected line definitions and unlinks permission buttons without modifying the source");
        Check(Reject(()=>deletion.Apply(library,new[]{Route()})),"station deletion with connected lines is blocked while any route remains active");
        Check(PanelConnections.Ports(indicator)==0&&PanelConnections.RailLineCount(indicator)==0&&!CircuitDiagramAssignment.RailField(indicator),"permission indicators neither create track connections nor become detection boundaries");
        copy=library.Clone();copy.FreeLines.Clear();Check(Reject(()=>copy.Validate("world")),"a line referenced by a diagram indicator cannot be removed before unlinking");
        var drawing=library.Desks[0].Panel.Clone();string before=JsonConvert.SerializeObject(drawing);Check(Reject(()=>PanelEditing.Draw(drawing,0,2,4,2))&&before==JsonConvert.SerializeObject(drawing),"drawing through a permission indicator rejects atomically instead of converting its line reference to a track tile");
        indicator.Ports=17;Check(Reject(()=>library.Desks[0].Panel.Put(indicator)),"permission indicators cannot be assigned physical rail ports");
        var inlineDoc=new PanelDocument{WorldKey="world"};inlineDoc.Put(new PanelTile{X=3,Y=2,Kind=PanelTileKind.Straight,Rotation=1,Section=new TrackSection{Segment="S",From=20,To=30},BlockId="GFM",CircuitRails=new(){[0]="GFM",[4]="GFM"}});
        int oldPorts=PanelConnections.Ports(inlineDoc.At(3,2));PanelEditing.PlaceField(inlineDoc,3,2,PanelTileKind.LinePermission);var inline=inlineDoc.At(3,2);
        Check(inline.InlinePermission&&inline.BlockId=="GFM"&&inline.Section.From==20&&inline.CircuitRails.Count==2&&PanelConnections.Ports(inline)==oldPorts&&CircuitDiagramAssignment.RailField(inline),"inline placement preserves track geometry, detection sections and both half-rail bindings");
        var inlineRound=JsonConvert.DeserializeObject<PanelDocument>(JsonConvert.SerializeObject(inlineDoc));inlineRound.Validate("world");
        Check(inlineRound.At(3,2).SameContent(inline)&&PanelConnections.RailLineCount(inline)>0&&EditorContextPolicy.FieldCategories(inline).Contains(EditorFieldCategory.Detection),"inline modules serialize and remain connected editable detection fields");
        inlineDoc.Put(new PanelTile{X=3,Y=1,Kind=PanelTileKind.Straight,Rotation=1});new PanelDeletion(inlineDoc,new PanelRegion{X=3,Y=2},true).Apply(inlineDoc,true);var below=inlineDoc.At(3,2);
        Check(below!=null&&below.Kind==PanelTileKind.Straight&&below.BlockId=="GFM"&&below.CircuitRails.Count==2&&!below.InlinePermission&&below.PermissionAuxiliary==null,"removing an inline module keeps the connected underlying detection rail");
        var auxiliary=new AuxiliaryTarget{Function=AuxiliaryFunction.LinePermission,PermissionLine=line.Id,Name="Permission"};auxiliary.Validate();
        Check(auxiliary.Endpoint()==null&&!AuxiliaryTarget.Accepts(auxiliary.Endpoint(),false)&&!AuxiliaryTarget.Accepts(auxiliary.Endpoint(),true),"permission-only auxiliary buttons need no world anchor and cannot become train or shunt destinations");
        var legacyTarget=JsonConvert.DeserializeObject<AuxiliaryTarget>("{\"Anchor\":{\"Segment\":\"S\",\"Meters\":10,\"Scale\":1}}");legacyTarget.Validate();
        Check(legacyTarget.Function==AuxiliaryFunction.RouteDestination&&legacyTarget.Endpoint()!=null,"legacy auxiliary targets retain their route-destination function and approach settings");
        var bound=library.Clone();bound.Desks[0].Panel.Put(new PanelTile{Kind=PanelTileKind.AuxiliaryTarget,X=4,Y=2,Target=auxiliary});var linked=bound.Desks[0].Panel.At(2,2).Clone();linked.PermissionAuxiliary=auxiliary.Id;bound.Desks[0].Panel.Put(linked);bound.Validate("world");
        Check(JsonConvert.DeserializeObject<DeskLibrary>(JsonConvert.SerializeObject(bound)).Desks[0].Panel.At(2,2).PermissionAuxiliary==auxiliary.Id,"line modules and auxiliary buttons share stable line and target IDs across save transfer");
        var badLink=bound.Clone();badLink.Desks[0].Panel.At(4,2).Target.PermissionLine=Guid.NewGuid().ToString("N");Check(Reject(()=>badLink.Validate("world")),"module and permission button cannot refer to different or missing lines");
        badLink=bound.Clone();badLink.Desks[0].Panel.Tiles.RemoveAll(t=>t.Target!=null);Check(Reject(()=>badLink.Validate("world")),"a linked permission button cannot disappear silently from its module");
        var removed=new DeskRemoval(bound,stationA).Apply(bound,Array.Empty<RouteDefinition>());removed.Validate("world");Check(removed.Desks[0].Panel.At(4,2).Target.PermissionLine=="","removing a neighbouring station unbinds its permission-only auxiliary controls without deleting world objects");
        var occupancy=TrackOccupancy.Clear;line.Automatic=false;
        var gate=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>occupancy};gate.Configure(new[]{line},_=>null);
        Check(Reject(()=>Reserve(gate,Route())),"new lines admit no departure before initial complete-clear proving");
        gate.Observe(Array.Empty<RouteRun>(),1);gate.Observe(Array.Empty<RouteRun>(),1);gate.Observe(Array.Empty<RouteRun>(),double.NaN);Check(gate.Get(line.Id).ClearChecks==1,"duplicate or invalid sample times cannot accelerate permission initialization");
        gate.Observe(Array.Empty<RouteRun>(),2);gate.Observe(Array.Empty<RouteRun>(),3);var request=Route();
        Check(gate.Get(line.Id).Direction==1,"initial clear proving establishes the configured normal owner without a route request");
        using(gate.Reserve(new[]{request})){}Check(!gate.Get(line.Id).Held&&gate.Get(line.Id).Direction==1&&gate.Get(line.Id).ClearChecks==3,"uncommitted route admission rolls back holds and leaves permission ownership intact");
        Check(Reject(()=>Reserve(gate,Route(reverse:true)))&&gate.Get(line.Id).Direction==1,"an opposing departure cannot take the neighbour's permission");
        long initialRevision=gate.Get(line.Id).Revision;
        Check(Reject(()=>gate.RequestPermission(line.Id,stationA,initialRevision))&&Reject(()=>gate.RequestPermission(line.Id,Guid.NewGuid().ToString("N"),initialRevision)),"owner and unrelated stations cannot request permission from themselves or another line");
        gate.RequestPermission(line.Id,stationB,initialRevision);
        Check(gate.Get(line.Id).Direction==1&&gate.Get(line.Id).RequestedDirection==-1,"an explicit neighbour request is pending without transferring authority");
        Check(Reject(()=>gate.GivePermission(line.Id,stationB,gate.Get(line.Id).Revision,Array.Empty<RouteRun>()))&&Reject(()=>gate.GivePermission(line.Id,stationA,initialRevision,Array.Empty<RouteRun>())),"requesting end cannot take permission and stale controls cannot give it");
        Check(Reject(()=>gate.CancelRequest(line.Id,stationA,gate.Get(line.Id).Revision)),"only the requesting station may cancel its request");
        Reserve(gate,request);Check(gate.Get(line.Id).Held&&gate.Get(line.Id).Direction==1,"pending requests do not remove the current owner's departure permission");
        Check(Reject(()=>gate.GivePermission(line.Id,stationA,gate.Get(line.Id).Revision,Array.Empty<RouteRun>()))&&Reject(()=>gate.Reset()),"a route hold prevents permission transfer and resetting the authority");
        var run=new RouteRun{Route=request,Stage=RouteStage.Cancelled};for(int i=4;i<=7;i++)gate.Observe(new[]{run},i);
        Check(gate.Get(line.Id).Held&&gate.Get(line.Id).ClearChecks==0,"cancelled routes with retained locks continue holding permission");
        occupancy=TrackOccupancy.Occupied;for(int i=8;i<=11;i++)gate.Observe(Array.Empty<RouteRun>(),i);Check(gate.Get(line.Id).Held,"train occupation retains direction even if its route record disappears");
        occupancy=TrackOccupancy.Clear;gate.Observe(Array.Empty<RouteRun>(),12);gate.Observe(Array.Empty<RouteRun>(),13);Check(gate.Get(line.Id).Held,"two clear samples cannot release a direction hold");
        gate.Observe(Array.Empty<RouteRun>(),14);Check(!gate.Get(line.Id).Held&&gate.Get(line.Id).Direction==1,"three whole-line clear readings release the hold while retaining its owner");
        occupancy=TrackOccupancy.Occupied;Check(Reject(()=>gate.GivePermission(line.Id,stationA,gate.Get(line.Id).Revision,Array.Empty<RouteRun>()))&&gate.Get(line.Id).Direction==1,"transfer rechecks present occupation after earlier clear samples");
        occupancy=TrackOccupancy.Clear;gate.GivePermission(line.Id,stationA,gate.Get(line.Id).Revision,Array.Empty<RouteRun>());
        Check(gate.Get(line.Id).Direction==-1&&gate.Get(line.Id).RequestedDirection==0&&Reject(()=>Reserve(gate,Route())),"only an owner's safe giving operation atomically transfers permission and consumes the request");
        Reserve(gate,Route(reverse:true));ClearChecks(gate,14);
        Check(Reject(()=>gate.GivePermission(line.Id,stationB,gate.Get(line.Id).Revision,Array.Empty<RouteRun>()))&&Reject(()=>gate.ResumeAutomatic(line.Id,stationB,gate.Get(line.Id).Revision)),"request-required manual lines prevent unsolicited giving and unconfigured automatic operation");
        gate.RequestPermission(line.Id,stationA,gate.Get(line.Id).Revision);gate.CancelRequest(line.Id,stationA,gate.Get(line.Id).Revision);
        Check(gate.Get(line.Id).RequestedDirection==0&&gate.Get(line.Id).Direction==-1,"cancelling a request preserves current ownership");
        var following=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>occupancy};following.Configure(new[]{line},_=>null);ClearChecks(following);Reserve(following,Route());occupancy=TrackOccupancy.Occupied;
        Reserve(following,Route());Check(following.Get(line.Id).Direction==1,"same-direction following trains retain permission while their own route and block gates prove availability");
        occupancy=TrackOccupancy.Unknown;Check(Reject(()=>Reserve(following,Route())),"following operation cannot bypass unknown line detection");occupancy=TrackOccupancy.Clear;
        var automatic=line.Clone();automatic.Automatic=true;var autoGate=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>occupancy};autoGate.Configure(new[]{automatic},_=>null);ClearChecks(autoGate);
        Check(Reject(()=>Reserve(autoGate,Route(reverse:true)))&&autoGate.Get(line.Id).RequestedDirection==0,"automatic mode does not generate a request or steal ownership during route admission");
        autoGate.RequestPermission(line.Id,stationB,autoGate.Get(line.Id).Revision);occupancy=TrackOccupancy.Occupied;ClearChecks(autoGate,3);
        Check(autoGate.Get(line.Id).Direction==1&&autoGate.Get(line.Id).RequestedDirection==-1,"automatic replies wait while occupation prevents complete clear proving");
        occupancy=TrackOccupancy.Clear;ClearChecks(autoGate,6);Check(autoGate.Get(line.Id).Direction==-1&&autoGate.Get(line.Id).RequestedDirection==0,"configured automatic granting answers explicit requests only after safe clear proving");
        var directional=Line(mode:LineTrackMode.Directional);var oneWay=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Clear};oneWay.Configure(new[]{directional},_=>null);ClearChecks(oneWay);
        Check(Reject(()=>Reserve(oneWay,Route(reverse:true)))&&Reject(()=>oneWay.RequestPermission(directional.Id,stationB,oneWay.Get(directional.Id).Revision)),"directional tracks reject opposing routes and reverse requests");
        Reserve(oneWay,Route());Check(oneWay.Get(directional.Id).Held,"fixed directional tracks still supervise ordinary route holds");
        var independent=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Clear};var other=Line("T");other.NormalDirection=-1;independent.Configure(new[]{line,other},_=>null);ClearChecks(independent);Reserve(independent,Route());Reserve(independent,Route("T",true));
        Check(independent.Get(line.Id).Direction==1&&independent.Get(other.Id).Direction==-1,"separate GWB tracks retain independent opposing normal permissions");
        var transactional=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Clear};transactional.Configure(new[]{line},_=>null);ClearChecks(transactional);
        var blocks=new DirectionBlockAuthority{Enabled=true,Occupancy=_=>TrackOccupancy.Clear,Blocks=new(){new DirectionBlock{Id="BL",Axis=line.Axis}}};
        Check(Reject(()=>new CombinedRouteAdmission(blocks,transactional).Reserve(new[]{Route(reverse:true)}))&&blocks.Leases.Count==0&&!transactional.Get(line.Id).Held,"rejected line permission rolls back the preceding automatic block reservation");
        blocks.Occupancy=_=>TrackOccupancy.Occupied;
        Check(Reject(()=>new CombinedRouteAdmission(blocks,transactional).Reserve(new[]{Route()}))&&transactional.Get(line.Id).Direction==1&&!transactional.Get(line.Id).Held,"owning permission never bypasses a separate occupied-block refusal");
        long oldGeneration=transactional.Get(line.Id).Revision;transactional.Reset();transactional.Configure(new[]{line},_=>null);ClearChecks(transactional);
        Check(transactional.Get(line.Id).Revision>oldGeneration&&Reject(()=>transactional.RequestPermission(line.Id,stationB,oldGeneration)),"removing and recreating a line invalidates old controls even when its stable ID is reused");
        var unknown=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Unknown};unknown.Configure(new[]{line},_=>null);ClearChecks(unknown);
        Check(Reject(()=>Reserve(unknown,Route()))&&unknown.Get(line.Id).Direction==0&&unknown.Get(line.Id).ClearChecks==0,"unknown startup occupancy cannot establish an owner");
        var invalid=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Clear};invalid.Configure(new[]{line},_=>"GFM missing");ClearChecks(invalid);
        Check(Reject(()=>Reserve(invalid,Route()))&&invalid.Get(line.Id).Direction==0,"changed topology and missing detection prevent initialization and departure");
        var off=new LineDirectionAuthority{BlockEnabled=false,Occupancy=_=>TrackOccupancy.Clear};off.Configure(new[]{line},_=>null);ClearChecks(off);Check(Reject(()=>Reserve(off,Route()))&&off.Get(line.Id).Direction==0,"disabling block coordination does not bypass configured line protection");
        var fresh=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Clear};fresh.Configure(round.FreeLines,_=>null);Check(fresh.Get(line.Id).Direction==0&&!fresh.Get(line.Id).Held&&fresh.Get(line.Id).RequestedDirection==0,"loading restores configuration without restoring live owner, requests, holds or signal authority");
        bool externalHold=false;var extra=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Clear,AdditionalHold=_=>externalHold};extra.Configure(new[]{line},_=>null);ClearChecks(extra);Reserve(extra,Route());extra.RequestPermission(line.Id,stationB,extra.Get(line.Id).Revision);externalHold=true;ClearChecks(extra,3);
        Check(extra.Get(line.Id).Held&&Reject(()=>extra.GivePermission(line.Id,stationA,extra.Get(line.Id).Revision,Array.Empty<RouteRun>())) ,"an external block lease prevents transfer after its route record has gone");
        externalHold=false;ClearChecks(extra,6);Check(!extra.Get(line.Id).Held,"ending an external block hold still requires complete clear proving");
        var pending=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Clear};pending.Configure(new[]{line},_=>null);ClearChecks(pending);Reserve(pending,Route());var changed=line.Clone();changed.Forward[0].Section.To=90;pending.Configure(new[]{changed},_=>null);
        Check(pending.NeedsRefresh&&pending.Get(line.Id).Definition.Forward[0].Section.To!=changed.Forward[0].Section.To&&Reject(()=>Reserve(pending,Route())),"configuration edits cannot replace a held physical line");
        ClearChecks(pending,3);pending.Configure(new[]{changed},_=>null);Check(!pending.NeedsRefresh&&pending.Get(line.Id).Definition.Forward[0].Section.To==changed.Forward[0].Section.To&&pending.Get(line.Id).Direction==0,"deferred configuration requires fresh initialization after the old line releases");
        var disabled=line.Clone();disabled.Enabled=false;int reads=0;var inactive=new LineDirectionAuthority{Occupancy=_=>{reads++;return TrackOccupancy.Clear;}};inactive.Configure(new[]{disabled},_=>null);ClearChecks(inactive);Check(reads==0,"disabled definitions do not poll occupancy");
        bool central=true;var takeover=new LineDirectionAuthority{BlockEnabled=true,Occupancy=_=>TrackOccupancy.Clear,AutomaticAllowed=_=>!central};takeover.Configure(new[]{automatic},_=>null);ClearChecks(takeover);takeover.RequestPermission(line.Id,stationB,takeover.Get(line.Id).Revision);ClearChecks(takeover,3);
        Check(takeover.Get(line.Id).Direction==1&&!takeover.IsAutomatic(takeover.Get(line.Id))&&Reject(()=>takeover.ResumeAutomatic(line.Id,stationA,takeover.Get(line.Id).Revision)),"central takeover pauses automatic request replies and prevents false resume");
        takeover.GivePermission(line.Id,stationA,takeover.Get(line.Id).Revision,Array.Empty<RouteRun>());Reserve(takeover,Route(reverse:true));ClearChecks(takeover,6);central=false;takeover.ResumeAutomatic(line.Id,stationB,takeover.Get(line.Id).Revision);takeover.RequestPermission(line.Id,stationA,takeover.Get(line.Id).Revision);ClearChecks(takeover,9);
        Check(takeover.Get(line.Id).Direction==1&&takeover.IsAutomatic(takeover.Get(line.Id)),"host can safely give during takeover and later resume explicit automatic request handling");
