        Check(direct.Get(line.Id).Direction==-1,"optional deliberate giving without a request remains an owner operation with full clear checks");
        var frame=new AutomationLiveFrame{Lines=new(){new AutomationStatus{Id=line.Id,Direction=-1,RequestedDirection=1,Revision=8,State="held"}}};frame.Validate();var live=JsonConvert.DeserializeObject<AutomationLiveFrame>(JsonConvert.SerializeObject(frame));
        Check(live.Lines.Single().Direction==-1&&JsonConvert.DeserializeObject<AutomationLiveFrame>("{}").Lines.Count==0,"line permission indications synchronize as bounded live data with backward-compatible empty defaults");
        Check(live.Lines[0].RequestedDirection==1&&live.Lines[0].Revision==8,"permission request and revision synchronize separately from owner and block state");
